(()=>{'use strict';const INDEX='player-profiles/index.json?v=20260729-unified-v1',BASE='player-profiles/';const root=document.getElementById('player-root');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toLowerCase();const n=v=>Number(v)||0;const fmt=v=>n(v).toLocaleString('pt-BR');const avg=(a,b)=>b?(n(a)/n(b)).toFixed(2):'0.00';const params=new URLSearchParams(location.search);function stat(label,value,sub='',rank=''){return`<div class="stat-card"><small>${esc(label)}</small><strong>${esc(value)}</strong>${sub?`<span>${esc(sub)}</span>`:''}${rank?`<span class="rank-pill">#${esc(rank)}</span>`:''}</div>`}async function resolveId(){const direct=params.get('id');if(direct)return direct;const wanted=params.get('jogador')||params.get('player')||'';const team=params.get('time')||params.get('team')||'';if(!wanted)return'';const idx=await fetch(INDEX,{cache:'default'}).then(r=>{if(!r.ok)throw new Error('Índice de jogadores indisponível');return r.json()});const matches=(idx.players||[]).filter(p=>norm(p.name)===norm(wanted)||(p.aliases||[]).some(a=>norm(a)===norm(wanted)));if(team){const tn=norm(team);const exact=matches.find(p=>norm(p.team)===tn||(p.teams||[]).some(t=>norm(t)===tn)||((tn==='loud'||tn==='loudsnickers')&&(p.teams||[]).some(t=>['loud','loudsnickers'].includes(norm(t)))));if(exact)return exact.id}return matches[0]?.id||''}function editionRow(e){return`<div class="edition-row"><div><strong>${esc(e.edition)}</strong><small>${esc(e.team||e.status||'')}</small></div><div class="edition-stat"><b>${fmt(e.kills)}</b><span>Abates</span></div><div class="edition-stat"><b>${fmt(e.matches)}</b><span>Quedas</span></div><div class="edition-stat"><b>${Number(e.avg||0).toFixed(2)}</b><span>Média</span></div><div class="edition-stat"><b>${e.damage?fmt(e.damage):'—'}</b><span>Dano</span></div></div>`}function teamCard(e){return`<div class="team-history-card"><img src="${esc(e.logo||'escudo.webp')}" onerror="this.onerror=null;this.src='escudo.webp'" alt=""><div><strong>${esc(e.team)}</strong><small>${esc(e.edition)}</small></div></div>`}function render(p){document.title=`${p.name} | Central Free Fire`;const roster=p.currentRoster||{};const s2=p.s2||{kills:0,damage:0,assists:0,matches:0,mvp:0};const latest=p.ffws||null;const latestTitle=latest?'FFWS BR 2026 S1 — última edição concluída':'Última temporada concluída';const badges=[roster.captain?'<span class="profile-badge gold">Capitão</span>':'',roster.rookie?'<span class="profile-badge">Estreante na S2</span>':'',roster.starter?'<span class="profile-badge">Titular</span>':roster.rosterStatus?`<span class="profile-badge">${esc(roster.rosterStatus)}</span>`:''].join('');root.innerHTML=`<section class="profile-hero"><div class="profile-photo-wrap"><img class="profile-photo" src="${esc(p.photo||'silhueta.webp')}" onerror="this.onerror=null;this.src='silhueta.webp'" alt="${esc(p.name)}"><img class="profile-team-logo" src="${esc(p.currentTeamLogo||'escudo.webp')}" onerror="this.onerror=null;this.src='escudo.webp'" alt=""></div><div><div class="profile-kicker">Perfil unificado do jogador</div><h1 class="profile-name">${esc(p.name)}</h1>${p.currentTeam?`<a class="profile-team" href="equipe.html?time=${encodeURIComponent(p.currentTeam)}">${esc(p.currentTeam)}</a>`:''}<div class="profile-meta">${esc(p.role||roster.role||'Jogador')}${roster.fullName?` • ${esc(roster.fullName)}`:''}${roster.state?` • ${esc(roster.state)}`:''}</div><div class="profile-badges">${badges}</div></div></section><section class="profile-section"><div class="profile-section-head"><h2>Desempenho atual — FFWS BR 2026 S2</h2><p>${s2.matches?'Temporada em andamento':'Temporada ainda não iniciada'}</p></div><div class="stats-grid">${stat('Abates totais',fmt(s2.kills),`Média: ${avg(s2.kills,s2.matches)} /queda`)}${stat('Dano total',fmt(s2.damage),`Média: ${avg(s2.damage,s2.matches)} /queda`)}${stat('Assistências',fmt(s2.assists),`Média: ${avg(s2.assists,s2.matches)} /queda`)}${stat('Quedas jogadas',fmt(s2.matches))}${stat('MVPs recebidos',fmt(s2.mvp))}</div>${!s2.matches?'<div class="season-empty">O jogador está cadastrado na temporada atual, mas as estatísticas começarão a aparecer após as primeiras quedas.</div>':''}</section>${latest?`<section class="profile-section"><div class="profile-section-head"><h2>${latestTitle}</h2><p>${esc(latest.team||'')}</p></div><div class="stats-grid">${stat('Abates totais',fmt(latest.kills),`Média: ${avg(latest.kills,latest.matches)} /queda`,latest.rankKills)}${stat('Dano total',fmt(latest.damage),`Média: ${avg(latest.damage,latest.matches)} /queda`,latest.rankDamage)}${stat('Assistências',fmt(latest.assists),`Média: ${avg(latest.assists,latest.matches)} /queda`,latest.rankAssists)}${stat('Recorde de abates',fmt(latest.record),'Em um único dia')}${stat('MVPs recebidos',fmt(latest.mvp))}</div></section>`:''}<section class="profile-section"><div class="profile-section-head"><h2>Desempenho histórico — All-Time</h2><p>Competições registradas no site</p></div><div class="history-summary">${stat('Kills históricas',fmt(p.allTime?.kills))}${stat('Quedas jogadas',fmt(p.allTime?.matches))}${stat('Média histórica',Number(p.allTime?.avg||0).toFixed(2))}</div></section><section class="profile-section"><div class="profile-section-head"><h2>Histórico por edições</h2><p>FFWS Brasil, EWC e edições históricas cadastradas</p></div><div class="edition-list">${(p.editions||[]).slice().reverse().map(editionRow).join('')||'<div class="season-empty">Nenhuma edição cadastrada.</div>'}</div></section><section class="profile-section"><div class="profile-section-head"><h2>Histórico recente de equipes</h2></div><div class="team-history-list">${(p.teamHistory||[]).map(teamCard).join('')||'<div class="season-empty">Histórico de equipes em atualização.</div>'}</div></section><div class="source-note">Perfil único: os resultados da FFWS Brasil e da EWC são reunidos nesta mesma página.</div>`}async function boot(){try{const id=await resolveId();if(!id)throw new Error('Jogador não encontrado');const p=await fetch(`${BASE}${encodeURIComponent(id)}.json?v=20260729-unified-v1`,{cache:'default'}).then(r=>{if(!r.ok)throw new Error('Perfil não encontrado');return r.json()});render(p)}catch(e){root.innerHTML=`<div class="player-error"><strong>${esc(e.message||'Não foi possível abrir o perfil.')}</strong><a class="player-back" href="index.html">Voltar para a página inicial</a></div>`}}boot()})();
